{
  "requirements": [
    {
      "statement": "The withdrawal of consent does not affect any sharing of health information that occurred prior to the revocation.",
      "citations": [
        "dha-consent-access-standard-2025#0018"
      ]
    },
    {
      "statement": "Entities that accessed or received health information via the Health Information System (HIS) prior to the revocation of consent and incorporated that information into their own records may retain it.",
      "citations": [
        "dha-consent-access-standard-2025#0018"
      ]
    },
    {
      "statement": "If a patient opts out of the Health Information System (HIS), personal health information should continue to be received by the HIS from the entity, but patient identifiers must be anonymized in accordance with UAE Federal Law No. (45) of 2021 and the Policy for Health Data Protection and Confidentiality.",
      "citations": [
        "dha-consent-access-standard-2025#0018"
      ]
    },
    {
      "statement": "Personal health information should not be retrieved using 'Break the Glass' (BTG) access after a patient has opted out of the HIS.",
      "citations": [
        "dha-consent-access-standard-2025#0018"
      ]
    }
  ],
  "conflicts": [],
  "gaps": [],
  "comparisons": [],
  "caveats": [
    "The provided rules specify that the right to object to sharing PHI through HIS is not valid for sharing in EMR, public health portals, and insurance systems as per UAE Federal Law No. (2) of 2019 and the DHA Health Data Protection and Confidentiality Policy."
  ]
}
